public class Main {
    static void step() {
        try {
            System.out.print("1 ");
            int[] a = new int[2];
            a[5] = 1;
        } catch (ArrayIndexOutOfBoundsException e) {
            System.out.print("2 ");
            throw new IllegalStateException("x");
        } catch (IllegalStateException e) {
            System.out.print("3 ");
        } finally {
            System.out.print("4 ");
        }
        System.out.print("5 ");
    }
    public static void main(String[] args) {
        try {
            step();
        } catch (RuntimeException e) {
            System.out.print("6 ");
        }
        System.out.print("7");
    }
}

