import java.util.*;
class Registry<T> {
    private static T defaultItem;                    // L1
    private T current;                               // L2
    private List<T> items = new ArrayList<>();       // L3
    T make() { return new T(); }                     // L4
    boolean check(Object o) {
        return o instanceof List<String>;            // L5
    }
    @SuppressWarnings("unchecked")
    T[] snapshot() { return (T[]) items.toArray(); } // L6
    T[] fresh() { return new T[10]; }                // L7
}

class Dispenser {
    // post-condition: returns exactly `pills` pills (for any pills >= 1)
    int dispense(int pills) {
        return pills;
    }
}

class BudgetDispenser extends Dispenser {
    @Override
    int dispense(int pills) {
        return Math.min(pills, 10);   // never gives more than 10
    }
}
